package com.eccraft.npc;
import com.eccraft.quest.QuestManager;import com.google.gson.*;import net.fabricmc.fabric.api.networking.v1.*;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.Entity;import java.util.*;
public final class NpcDialogueManager{
 public static void register(){PayloadTypeRegistry.clientboundPlay().registerLarge(NpcPayloads.Open.TYPE,NpcPayloads.Open.CODEC,262144);PayloadTypeRegistry.serverboundPlay().register(NpcPayloads.Choose.TYPE,NpcPayloads.Choose.CODEC);PayloadTypeRegistry.serverboundPlay().register(NpcPayloads.Close.TYPE,NpcPayloads.Close.CODEC);ServerPlayNetworking.registerGlobalReceiver(NpcPayloads.Choose.TYPE,(p,c)->choose(c.player(),p));ServerPlayNetworking.registerGlobalReceiver(NpcPayloads.Close.TYPE,(p,c)->{Entity e=c.player().level().getEntity(p.entityId());if(e instanceof NpcNormalEntity n)n.release(c.player().getUUID());});}
 public static void open(ServerPlayer p,NpcNormalEntity n,String dialogue){var def=NpcRegistry.INSTANCE.definitions.get(n.definition());String id=dialogue==null&&def!=null?def.dialogue():dialogue;var d=NpcRegistry.INSTANCE.dialogues.get(id);if(d==null){p.sendSystemMessage(net.minecraft.network.chat.Component.literal("NPC 对话不存在: "+id));n.release(p.getUUID());return;}JsonObject root=new JsonObject();root.addProperty("dialogue",id);root.addProperty("speaker",d.speaker().isBlank()?n.display():d.speaker());root.addProperty("text",d.text());JsonArray opts=new JsonArray();for(int i=0;i<d.options().size();i++){var o=d.options().get(i);if(matches(p,o.conditions())){JsonObject x=new JsonObject();x.addProperty("index",i);x.addProperty("text",o.text());opts.add(x);}}root.add("options",opts);n.refreshLock();ServerPlayNetworking.send(p,new NpcPayloads.Open(n.getId(),root.toString()));}
 private static boolean matches(ServerPlayer p,List<NpcRegistry.Condition> cs){for(var c:cs)if("quest_state".equals(c.type())&&!c.state().equals(QuestManager.state(p,c.quest())))return false;return true;}
 private static void choose(ServerPlayer p,NpcPayloads.Choose payload){Entity e=p.level().getEntity(payload.entityId());if(!(e instanceof NpcNormalEntity n)||!n.isTalkingTo(p))return;var d=NpcRegistry.INSTANCE.dialogues.get(payload.dialogue());if(d==null||payload.option()<0||payload.option()>=d.options().size())return;var o=d.options().get(payload.option());if(!matches(p,o.conditions()))return;String next=null;boolean close=false;for(var a:o.actions())switch(a.type()){case"next"->next=a.dialogue();case"close"->close=true;case"quest_accept"->QuestManager.accept(p,a.quest());case"quest_complete"->QuestManager.forceComplete(p,a.quest());case"quest_submit"->QuestManager.submit(p,a.quest());case"quest_claim"->QuestManager.claim(p,a.quest());case"open_quest_page"->{QuestManager.sync(p,true);close=true;}}QuestManager.sync(p);if(close){n.release(p.getUUID());ServerPlayNetworking.send(p,new NpcPayloads.Open(n.getId(),"{}"));}else open(p,n,next==null?payload.dialogue():next);}
 private NpcDialogueManager(){}
}
